const maxPlanItemPosition = `-- name: MaxPlanItemPosition :one
SELECT CAST(COALESCE(MAX(position), 0) AS INTEGER) AS max_position
FROM period_plan_items
WHERE period_plan_id = ?
`

func (q *Queries) MaxPlanItemPosition(ctx context.Context, periodPlanID int64) (int64, error) {
	row := q.db.QueryRowContext(ctx, maxPlanItemPosition, periodPlanID)
	var max_position int64
	err := row.Scan(&max_position)
	return max_position, err
}

const updatePlanItem = `-- name: UpdatePlanItem :one
UPDATE period_plan_items
SET text = COALESCE(?1, text),
    status = COALESCE(?2, status),
    priority = COALESCE(?3, priority),
    is_important = COALESCE(?4, is_important),
    is_urgent = COALESCE(?5, is_urgent),
    project_scope = COALESCE(?6, project_scope),
    position = COALESCE(?7, position),
    updated_at = ?8
WHERE id = ?9
RETURNING id, period_plan_id, text, status, project_scope, parent_item_id, deferred_from_item_id, position, created_at, updated_at, priority, is_important, is_urgent
`

type UpdatePlanItemParams struct {
	Text         *string `json:"text"`
	Status       *string `json:"status"`
	Priority     *string `json:"priority"`
	IsImportant  *int64  `json:"is_important"`
	IsUrgent     *int64  `json:"is_urgent"`
	ProjectScope *string `json:"project_scope"`
	Position     *int64  `json:"position"`
	UpdatedAt    int64   `json:"updated_at"`
	ID           int64   `json:"id"`
}

// PUT /plan-items/{id} rewrites only the fields present in the body; updated_at
// always is. COALESCE(narg) is the sqlc spelling of drizzle's "only set defined
// keys". parent_item_id has its own statement below because null is a real
// value (clearing the link), not "absent".
func (q *Queries) UpdatePlanItem(ctx context.Context, arg UpdatePlanItemParams) (PeriodPlanItem, error) {
	row := q.db.QueryRowContext(ctx, updatePlanItem,
		arg.Text,
		arg.Status,
		arg.Priority,
		arg.IsImportant,
		arg.IsUrgent,
		arg.ProjectScope,
		arg.Position,
		arg.UpdatedAt,
		arg.ID,
	)
	var i PeriodPlanItem
	err := row.Scan(
		&i.ID,
		&i.PeriodPlanID,
		&i.Text,
		&i.Status,
		&i.ProjectScope,
		&i.ParentItemID,
		&i.DeferredFromItemID,
		&i.Position,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.Priority,
		&i.IsImportant,
		&i.IsUrgent,
	)
	return i, err
}

